(1, 'App\\Models\\Category', 1, 'منتجات العناية بالشعر', 'اكتشف مجموعة متنوعة من منتجات العناية بالشعر، بما في ذلك الشامبو والبلسم والماسكات والزيوت والعلاجات للحصول على شعر صحي وجميل.', '', '', '', '', '0', '0', '0', '0', '0', '0', '0', '2026-07-04-6a49317f6e1a2.webp', '2026-07-04 23:14:55', '2026-07-04 23:15:12'),
(2, 'App\\Models\\Category', 2, 'مزيلات العرق', 'تسوق مزيلات العرق التي توفر انتعاشًا يدوم طويلًا وحماية فعالة من الروائح طوال اليوم.', '', '', '', '', '0', '0', '0', '0', '0', '0', '0', '2026-07-04-6a4931aec8367.webp', '2026-07-04 23:15:42', '2026-07-04 23:16:09'),
(3, 'App\\Models\\Category', 3, 'لوشن ومرطبات الجسم', 'اكتشف لوشن ومرطبات الجسم التي تمنح بشرتك ترطيبًا عميقًا ونعومة تدوم طوال اليوم.', '', '', '', '', '0', '0', '0', '0', '0', '0', '0', '2026-07-04-6a49321be5d89.webp', '2026-07-04 23:17:31', '2026-07-04 23:17:31'),
