('App\\Models\\Category', 3, 'sy', 'name', 'لوشن الجسم', 20),
('App\\Models\\Product', 3, 'sy', 'name', 'ميدي هيدرا مرطب 50 مل', 28),
('App\\Models\\Product', 3, 'sy', 'description', '<h3><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">ميدي هيدرا للترطيب</span></h3><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">مرطب مائي خفيف علي البشره ولا يسبب حب شباب.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">يصلح لجميع انواع البشره خاصه البشره المختلطه او الدهنيه.&nbsp;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">يوضع عدة مرات لترطيب الوجه والرقبه واليدين.&nbsp;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">ليس له اي اعراض جانبيه تذكر ويصلح للحامل والمرضع.&nbsp;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">مناسب لكل انواع البشره ولكل الاعمار.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">50 مل</span></p><p><br></p>', 29),
('App\\Models\\Product', 4, 'sy', 'name', 'ميدي سيروم فيتامين سي 30 مل', 30),
('App\\Models\\Product', 4, 'sy', 'description', '<h3><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">ميدي سيروم فيتامين سي</span></h3><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">يحتوي علي فيتامين سي تركيز 10% وفيتامينات اخرى للتفتيح والنضاره.&nbsp;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">&nbsp;يوضع علي البشره مره او مرتين في اليوم&nbsp;يمكن استخدامه بعد جلسه ديرما رولر. يصلح للاستخدام في الليل او النهار.&nbsp;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">ليس له اي اعراض جانبيه تذكر ويصلح للحامل والمرضع.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">مناسب لكل انواع البشره ولكل الاعمار.&nbsp;</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(1, 15, 28);\">30 مل</span></p><p><br></p>', 31),
