('App\\Models\\Category', 8, 'sy', 'name', 'العناية بالشعر', 33),
('App\\Models\\Category', 9, 'sy', 'name', 'العناية بالجسم', 34),
('App\\Models\\Category', 10, 'sy', 'name', 'عروض حصرية 🔥', 35),
('App\\Models\\Category', 11, 'sy', 'name', 'سيروم الوجه', 36),
('App\\Models\\Category', 12, 'sy', 'name', 'مرطبات الوجه', 37),
('App\\Models\\Category', 13, 'sy', 'name', 'منظفات الوجه', 38),
('App\\Models\\Category', 14, 'sy', 'name', 'شامبو الشعر', 39),
('App\\Models\\Category', 15, 'sy', 'name', 'بلسم وماسكات الشعر', 40),
('App\\Models\\Category', 16, 'sy', 'name', 'زيوت الشعر', 41),
('App\\Models\\Category', 17, 'sy', 'name', 'لوشن ومرطبات الجسم', 42),
('App\\Models\\Product', 5, 'sy', 'name', 'ميدي سيروم اكسترا سي 30 مل بفيتامين سي', 43),
('App\\Models\\Product', 5, 'sy', 'description', '<p>ميدي سيروم اكسترا سي 30 مل هو منتج مثالي للعناية بالبشرة يحتوي على تركيز عالٍ من فيتامين سي بنسبة 15%</p>', 44),
('App\\Models\\Product', 6, 'sy', 'name', 'ميدي ريتينول 30 مل', 45),
('App\\Models\\Product', 6, 'sy', 'description', '<p>سيروم ميدي ريتينول يقلل المسام والحبوب ويوازن دهون البشرة لبشرة ناعمة وخالية من اللمعان.</p>', 46),
('App\\Models\\Product', 7, 'sy', 'name', 'ميدي هيالورونيك اسيد 30 مل', 47),
('App\\Models\\Product', 7, 'sy', 'description', '<p>سيروم ميدي هيالورونيك أسيد يرطب البشرة بعمق ويمنحها نعومة ونضارة طبيعية.</p>', 48),
('App\\Models\\Category', 18, 'sy', 'name', 'واقي الشمس', 49),
('App\\Models\\Product', 8, 'sy', 'name', 'جوفيلاب حمايه من الشمس 50+ شفاف', 50),
('App\\Models\\Product', 8, 'sy', 'description', '<p>جوفيلاب كريم حماية من الشمس SPF50 شفاف ☀️ مناسب لجميع أنواع البشرة، خاصة المختلطة والدهنية. ملمس خفيف غير دهني، خالٍ من البارابين، يحتوي على مواد مهدئة. يوضع كل ساعتين خلال النهار للحماية المثالية.</p>', 51),
('App\\Models\\Product', 9, 'sy', 'name', 'جوفيلاب حمايه من الشمس 50+ مع تفتيح', 52),
('App\\Models\\Product', 9, 'sy', 'description', '<p>جوفيلاب كريم حمايه من الشمس 50+ مع مادة الآربوتين للتفتيح.مناسب لجميع انواع البشره خاصة للبشره المختلطه او الدهنيه, ملمس خفيف غير دهني. مناسب للبشره الحساسه لانه خالي من البارابين ويحتوي علي مواد مهدئه للجلد. يوضع علي البشره كل ساعتين.</p>', 53),
('App\\Models\\Product', 10, 'sy', 'name', 'جوفيلاب TKN كريم تفتيح البشرة', 54),
('App\\Models\\Product', 10, 'sy', 'description', '<p>كريم TKN يتميز بقدرته على تفتيح البشرة ولا يسبب تهيج ويستخدام على الوجه بأكمله</p>', 55),
('App\\Models\\Product', 11, 'sy', 'name', 'جوفيلاب غسول للبشرة المختلطة والدهنية - 200 مل', 56),
('App\\Models\\Product', 11, 'sy', 'description', '<p>غسول جوفيلاب للبشرة الدهنية والمختلطة ينظف البشرة بعمق ويزيل الدهون الزائدة، مما يساعد على تقليل الحبوب ومنحك بشرة نقية ومنتعشة.</p><p> </p>', 57),
('App\\Models\\Product', 12, 'sy', 'name', 'جوفيلاب غسول للبشرة الجافة والحساسة - 200 مل', 58),
('App\\Models\\Product', 12, 'sy', 'description', '<p>غسول جوفيلاب للبشرة الجافة والحساسة ينظف البشرة بلطف مع ترطيب وتهدئة، ليمنحك بشرة ناعمة ومريحة يوميًا.</p><p> </p>', 59),
('App\\Models\\Product', 13, 'sy', 'name', 'جوفيلاب غسول لبشرة الاطفال الناعمة - 200 مل', 60),
('App\\Models\\Product', 13, 'sy', 'description', '<p>غسول جوفيلاب لبشرة الأطفال ينظف بلطف ويرطب البشرة الحساسة، ليحافظ على نعومة بشرة طفلك ويحميها من الجفاف.</p><p>&nbsp;</p>', 61),
('App\\Models\\Product', 14, 'sy', 'name', 'جوفيلاب مزيل عرق 50 مل', 62),
('App\\Models\\Product', 14, 'sy', 'description', '<p>مزيل عرق جوفيلاب يمنحك حماية فعالة من التعرق والروائح مع إحساس منعش يدوم طوال اليوم.</p><p>&nbsp;</p>', 63),
('App\\Models\\Product', 15, 'sy', 'name', 'جوفيلاب مزيل عرق و مضاد التعرق - 50 مل', 64),
('App\\Models\\Product', 15, 'sy', 'description', '<p>مزيل عرق جوفيلاب يمنحك حماية فعالة من التعرق والروائح مع إحساس منعش يدوم طوال اليوم.</p><p> </p>', 65),
('App\\Models\\Product', 16, 'sy', 'name', 'فيمي هير لوشن 15 أمبولة', 66),
('App\\Models\\Product', 16, 'sy', 'description', '<p><strong>لوشن فيمي هير</strong> هو ابتكار إيطالي متطور للعناية بالشعر الضعيف والمجهد. يعتمد على تقنية <strong>Micro-Emulsion</strong> التي تساعد على تعزيز امتصاص المكونات الفعالة داخل فروة الرأس، مما يساهم في تغذية بصيلات الشعر، وتقليل التساقط، ودعم نمو شعر أكثر كثافة وقوة.</p><h3>المميزات</h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>تقنية <strong>Micro-Emulsion</strong> لتعزيز امتصاص المكونات الفعالة.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يساعد على تقوية بصيلات الشعر من الجذور.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يساهم في تقليل تساقط الشعر.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يدعم كثافة الشعر ويحسن مظهره.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يحتوي على مكونات فعالة مثل <strong>Kopexil®</strong> و<strong>Saw Palmetto Extract</strong>.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>مناسب للرجال والنساء.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>مناسب للشعر الضعيف والمجهد.</li></ol><h3>طريقة الاستخدام</h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>ضع محتوى أمبول واحد على فروة رأس نظيفة وجافة أو رطبة قليلًا.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>دلك فروة الرأس بلطف لمدة 2–3 دقائق حتى يتم الامتصاص.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>لا يُشطف بعد الاستخدام.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يُستخدم حسب إرشادات الطبيب أو وفق البرنامج الموصى به.</li></ol><h3>التوصية</h3><p>لأفضل النتائج، استخدم اللوشن بانتظام لمدة <strong>3 أشهر على الأقل</strong>، ويُنصح باستخدامه مع <strong>كبسولات أو شامبو Feme Hair</strong> للحصول على برنامج متكامل للعناية بالشعر.</p>', 67),
('App\\Models\\Product', 17, 'sy', 'name', 'شامبو فيمي هير بالكافيين واليوريا 5% 200مل', 68),
('App\\Models\\Product', 17, 'sy', 'description', '<p><strong>شامبو Feme Hair</strong> هو شامبو مرطب مصمم للعناية اليومية بجميع أنواع الشعر. يتميز بتركيبة غنية بـ <strong>الكافيين، والأرجينين، و5% يوريا</strong> للمساعدة في تنشيط فروة الرأس، وتقوية بصيلات الشعر، والحفاظ على توازنها الطبيعي. كما يتمتع بدرجة حموضة <strong>pH 5.5</strong> للحفاظ على صحة فروة الرأس، وهو خالٍ من المواد المنظفة القاسية والمواد المسببة للحساسية، مما يجعله مناسبًا للاستخدام اليومي.</p><h3>المميزات</h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يرطب الشعر وفروة الرأس.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يحتوي على <strong>الكافيين</strong> للمساعدة في تنشيط فروة الرأس.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يحتوي على <strong>الأرجينين</strong> لدعم صحة الشعر.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>غني بـ <strong>5% يوريا</strong> للمساعدة في ترطيب فروة الرأس.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يحافظ على درجة حموضة <strong>pH 5.5</strong> المناسبة لفروة الرأس.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يساعد على تقوية بصيلات الشعر.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>خالٍ من المواد المنظفة القاسية والمواد المسببة للحساسية.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>مناسب لجميع أنواع الشعر.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>مناسب للاستخدام اليومي.</li></ol><h3>طريقة الاستخدام</h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>بلل الشعر جيدًا بالماء.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>ضع كمية مناسبة من الشامبو ودلك فروة الرأس بلطف لمدة 2–3 دقائق.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>اشطف الشعر جيدًا بالماء.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>كرر الاستخدام عند الحاجة.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>مناسب للاستخدام اليومي.</li></ol><h3>التوصية</h3><p>لأفضل النتائج، استخدم الشامبو بانتظام مع <strong>لوشن Feme Hair</strong> و<strong>كبسولات Feme Hair</strong> ضمن روتين متكامل للعناية بالشعر وتقليل التساقط وتعزيز كثافته.</p>', 69),
('App\\Models\\Product', 18, 'sy', 'name', 'زيت الروزماري فيمي هير 50 مل', 70),
('App\\Models\\Product', 18, 'sy', 'description', '<p><strong>زيت Feme Hair Rosemary Oil</strong> هو تركيبة متطورة تعتمد على تقنية <strong>Microemulsion</strong> التي تساعد على تعزيز امتصاص المكونات الفعالة داخل فروة الرأس. يجمع بين <strong>زيت إكليل الجبل (Rosemary Oil)</strong> و<strong>الكافيين</strong> و<strong>الأرجينين</strong> للمساعدة في تقوية الشعر، وتغذية البصيلات، ودعم نمو شعر أكثر كثافة وصحة.</p><h3>المميزات</h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>تقنية <strong>Microemulsion</strong> لتعزيز امتصاص المكونات الفعالة.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يحتوي على زيت إكليل الجبل (Rosemary Oil).</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>مدعم بالكافيين والأرجينين.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يساعد على تقوية بصيلات الشعر.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يدعم نمو شعر أكثر كثافة وصحة.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يغذي فروة الرأس ويحسن مظهر الشعر.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>مناسب لجميع أنواع الشعر.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>مناسب للاستخدام المنتظم.</li></ol><h3>طريقة الاستخدام</h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>ضع <strong>4–5 قطرات</strong> مباشرة على فروة رأس نظيفة.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>دلك فروة الرأس بلطف لمدة 2–3 دقائق حتى يتم امتصاص الزيت.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يُترك على فروة الرأس دون شطف.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>يستخدم يوميًا أو حسب إرشادات المختص.</li></ol><h3>التوصية</h3><p>لأفضل النتائج، استخدم الزيت بانتظام مع <strong>شامبو Feme Hair</strong> و<strong>لوشن Feme Hair</strong> و<strong>كبسولات Feme Hair</strong> ضمن روتين متكامل للعناية بالشعر، للحصول على شعر أكثر قوة وكثافة وصحة.</p>', 71),
